+      });
+    } else {
+      console.log("⊘ Skipped (AZURE_STORAGE_ACCOUNT_NAME not set)\n");
+    }
+
+    console.log("=== All examples completed successfully ===");
+  } catch (error) {
+    console.error("\n=== Error occurred ===");
+    handleAuthenticationError(error);
+    process.exit(1);
+  }
+}
+
+// Run if executed directly
